python3 - <<'PY'
import json, re, zipfile
import xml.etree.ElementTree as ET
from io import BytesIO

TEMPLATE = '/root/training_feedback_ready.hwpx'
JSON_PATH = '/root/training_feedback.json'

with open(JSON_PATH, 'r', encoding='utf-8') as f:
    data = json.load(f)

# Build replacement map
rep = {}
for k,v in data.items():
    if v is None:
        rep[k] = ''
    else:
        rep[k] = str(v)

# Transformations
if '참석자수' in rep:
    rep['참석자수'] = re.sub(r'[^0-9]', '', rep['참석자수'])

if '만족도' in rep:
    m = re.search(r'(\d+(?:\.\d+)?)', rep['만족도'])
    score = m.group(1) if m else rep['만족도']
    rep['만족도'] = f"{score}점 (5.0점 만점)"

if '종합의견' in rep:
    base = rep['종합의견']
    suffix = '후속 심화반 검토 요망.'
    if base.endswith(' '):
        rep['종합의견'] = base + suffix
    else:
        rep['종합의견'] = base + ' ' + suffix

# Read all ZIP entries
with zipfile.ZipFile(TEMPLATE, 'r') as zin:
    files = {name: zin.read(name) for name in zin.namelist()}

HP_NS = 'http://www.hancom.co.kr/hwpml/2010/HWPML'
NS = {'hp': HP_NS}

def localname(tag: str) -> str:
    return tag.split('}', 1)[1] if tag.startswith('{') else tag

modified_files = []

for name, raw in list(files.items()):
    if not name.lower().endswith('.xml'):
        continue
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        continue
    if '{{' not in text:
        continue

    # Parse XML
    root = ET.fromstring(text)

    # Track if any placeholders were present/replaced in each paragraph
    for p in root.findall('.//hp:p', NS):
        # detect placeholders in this paragraph
        had_placeholder = False
        for t in p.findall('.//hp:t', NS):
            if t.text and '{{' in t.text:
                had_placeholder = True
                new_text = t.text
                for key, val in rep.items():
                    new_text = new_text.replace('{{'+key+'}}', val)
                t.text = new_text

        if had_placeholder:
            # Remove layout cache related elements within this paragraph
            # Remove any direct child whose localname contains 'lineseg'
            for child in list(p):
                ln = localname(child.tag).lower()
                if 'lineseg' in ln:
                    p.remove(child)
                else:
                    # Some caches could be nested; remove descendants with lineseg*
                    for sub in list(child):
                        if 'lineseg' in localname(sub.tag).lower():
                            child.remove(sub)

    # Serialize back
    new_xml = ET.tostring(root, encoding='utf-8', xml_declaration=False)
    if b'{{' in new_xml:
        # Provide context for remaining placeholders
        remaining = sorted(set(re.findall(rb'\{\{[^}]+\}\}', new_xml)))
        raise SystemExit(f"Unreplaced placeholders in {name}: {remaining[:20]}")

    files[name] = new_xml
    modified_files.append(name)

# Rewrite ZIP
with zipfile.ZipFile(TEMPLATE, 'w', zipfile.ZIP_DEFLATED) as zout:
    for name, raw in files.items():
        zout.writestr(name, raw)

print('Modified XML files:', modified_files)
PY

